public struct VersionInput: Codable, Sendable, Hashable {
    public init() {
    }
}

public struct VersionOutput: Codable, Sendable, Hashable {
    public init() {
    }
}

/// Version: Print the m365crawl version, commit and build date.
@MainActor
public enum VersionAction {
    public static let id = "version"
    /// The app's handler; every door calls it.
    public static var perform: (@MainActor @Sendable (VersionInput) async throws -> VersionOutput)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (VersionInput, Result<VersionOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: VersionInput) async throws -> VersionOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct VersionIntent: AppIntent {
    public static let title: LocalizedStringResource = "Version"
    public static let description = IntentDescription("Print the m365crawl version, commit and build date.")

    public init() {}

    public init(_ input: VersionInput) {
        self.init()
    }

    public var input: VersionInput {
        VersionInput()
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        let input = self.input
        let result: Result<VersionOutput, any Error>
        do { result = .success(try await VersionAction.run(input)) } catch { result = .failure(error) }
        if let dialog = VersionAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

/// The control for version: Button(_:intent:), the same intent Siri and Shortcuts run.
@available(iOS 17.0, macOS 14.0, watchOS 10.0, tvOS 17.0, *)
public struct VersionButton<Label: View>: View {
    public let input: VersionInput
    let label: Label

    public init(_ input: VersionInput, @ViewBuilder label: () -> Label) {
        self.input = input
        self.label = label()
    }

    public var body: some View {
        Button(intent: VersionIntent(input)) { label }
            .accessibilityHint(Text(verbatim: "Print the m365crawl version, commit and build date."))
    }
}

@available(iOS 17.0, macOS 14.0, watchOS 10.0, tvOS 17.0, *)
extension VersionButton where Label == Text {
    public init(_ input: VersionInput) {
        self.init(input) { Text(verbatim: "Version") }
    }
}

